"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["39297"],{44045(e){e.exports=JSON.parse('{"id":"V4-128","slug":"debt-yield","term":"Debt Yield","also_known_as":[],"difficulty":"Advanced","definition":"Debt yield is a measure used by commercial property lenders, calculated by dividing a property\u2019s net operating income by the amount of the loan.","explanation":["Debt yield shows the return a lender would earn on its loan if it had to take over the property, based on the property\u2019s current income. It is a simple measure of how much income supports the loan.","For example, a property with net operating income of 650,000 and a loan of 8,000,000 has a debt yield of 650,000 divided by 8,000,000, or about 8.1%.","Unlike loan-to-value and the debt service coverage ratio, debt yield does not depend on the property\u2019s valuation, the interest rate or the length of the loan. This makes it harder to inflate through optimistic valuations or low interest rates, which is why lenders began using it more widely after the 2008 financial crisis.","Lenders often set a minimum debt yield, such as 8% to 10%, depending on the property type and market conditions. A higher debt yield means less risk for the lender. Debt yield is used alongside other measures, such as loan-to-value and debt service coverage, when deciding how much to lend."],"note":"","total":1725,"prev":{"slug":"debt-to-income-ratio","term":"Debt-to-Income Ratio"},"next":{"slug":"decentralized-finance","term":"Decentralized Finance (DeFi)"}}')}}]);